function generatePassage(topic: PassageTopic) {
  const { title, sub, cat } = topic;
  let p1 = "";
  let p2 = "";
  let p3 = "";
  let p4 = "";

  if (cat === "History") {
    p1 = `Throughout the sweeping chronicle of human civilization, few subjects capture the historical imagination quite like ${title.toLowerCase()}. As chroniclers and modern archaeologists have documented, ${sub.toLowerCase()} It stands not merely as an isolated relic of an ancient century, but as an enduring testament to the ingenuity, ambition, and social organization of early societies. When we examine the historical context surrounding this milestone, we observe a civilization navigating profound structural transformations. Communities were actively grappling with the expansion of overland and maritime trade, the codification of civil laws, urban migration, and the preservation of communal memory. In this dynamic crucible, rulers, scholars, and skilled artisans forged innovative practices that laid the foundational architecture for modern institutions. By examining the primary artifacts, ancient inscriptions, and contemporary accounts that have survived the weathering of millennia, modern historians are able to reconstruct the social fabrics, political hierarchies, and philosophical convictions that defined this extraordinary epoch.`;
    p2 = `The practical execution of these endeavors required unprecedented logistical coordination, specialized craftsmanship, and empirical mastery. Long before the advent of mechanized industry or computerized computation, ancient builders and thinkers relied upon systematic trial and error, rigorous observation, and generational knowledge. They organized vast labor networks across geographical regions, surveyed rugged landscapes with surprising geometric precision, and mastered the physical properties of stone, timber, metal, ceramic, and water flow. Whether charting trade caravans across unforgiving desert trade routes, constructing civic aqueducts that conquered mountainous elevations, or transcribing vast libraries of papyrus and parchment scrolls, their accomplishments reflect a sophisticated grasp of resource management. Furthermore, these undertakings were rarely insular events; they served as vital crossroads where diverse cultures converged, exchanging culinary traditions, scientific terminology, spiritual beliefs, and artistic motifs.`;
    p3 = `Yet behind every monumental achievement lies an intricate story of human struggle, cultural resilience, and occasional catastrophe. The historical trajectory was rarely linear or uninterrupted; it was repeatedly punctuated by geopolitical upheavals, environmental droughts, epidemic disease, and economic volatility. In many instances, the sudden collapse or gradual decline of established dynasties resulted in the tragic dispersal of valuable archives and the abandonment of once-vibrant centers of learning. However, the underlying cultural memory survived in oral folklore, monastic copies, and buried archaeological strata, waiting to be rediscovered by future generations. When modern researchers brush away the accumulated dust from these antiquity sites, they uncover not dead monuments, but living dialogues about justice, civic duty, leadership, and our shared responsibilities toward posterity.`;
    p4 = `Ultimately, contemplating ${title.toLowerCase()} invites us to reflect upon our own place within the broader continuum of human heritage. The challenges confronted by our ancient forebears—balancing economic expansion with ecological stability, safeguarding vital knowledge against systemic loss, and fostering mutual trust across cultural boundaries—remain startlingly resonant in our contemporary global landscape. By engaging with these historical narratives through focused study and patient reflection, we gain invaluable perspective on the enduring resilience of the human spirit. History ceases to be a distant litany of dates and battles; instead, it becomes a mirror reflecting the fundamental hopes, vulnerabilities, and creative potential that unite humanity across time and space.`;
  } else if (cat === "Science & Space") {
    p1 = `The natural cosmos operates according to elegant mathematical principles and physical laws, exemplified with striking clarity by ${title.toLowerCase()}. As contemporary researchers have discovered, ${sub.toLowerCase()} From the earliest astronomical gazes at celestial canopies to modern spectroscopic analyses conducted from spaceborne orbital platforms, scientific investigation has continuously dismantled human misconceptions about the physical universe. What initially appeared to our ancestors as mysterious omens or static backdrops is now recognized as a dynamic, interconnected expanse governed by thermodynamics, gravitational attraction, quantum electrodynamics, and biological evolution. By probing the fundamental behaviors of matter, energy, and radiation across cosmic and microscopic scales, researchers unlock foundational insights into the mechanisms that govern everything from the smallest subatomic particles to the grandest superclusters of galaxies drifting across cosmic voids.`;
    p2 = `At the core of this scientific exploration lies the rigorous application of empirical methodology, reproducible experimentation, and specialized instrumentation. Scientists design experiments capable of isolating subtle physical phenomena, constructing sensors that measure imperceptible variations in temperature, atmospheric pressure, electromagnetic wavelength, and gravitational flux. In laboratory settings and remote field stations alike, theoretical hypotheses are systematically tested against quantifiable observational data. When analyzing ${title.toLowerCase()}, researchers must account for complex variables including atmospheric scattering, thermal noise, gravitational lensing, and statistical uncertainties. The development of advanced computational models has further amplified our analytic capabilities, enabling simulations that compress billions of years of stellar evolution or molecular interactions into digestible visual frameworks that illuminate underlying causal mechanisms.`;
    p3 = `Beyond theoretical equations and quantitative datasets, this field of inquiry reveals the profound interconnectedness of planetary and astrophysical systems. Matter forged within the nuclear furnaces of ancient collapsing supernovas was dispersed into interstellar nebulae, eventually coalescing into the terrestrial crusts, oceanic basins, and carbon-based molecules that constitute living organisms on our home planet. We are, in a very literal astrophysical sense, composed of stardust that has undergone billions of years of thermodynamic processing. Understanding these mechanisms not only satisfies our innate intellectual curiosity, but also equips human civilization to steward planetary environments, anticipate natural hazards, monitor biosphere health, and develop sustainable clean energy solutions capable of sustaining future generations.`;
    p4 = `As observational technology advances toward unprecedented thresholds of sensitivity and resolution, the ongoing study of ${title.toLowerCase()} continues to yield revelations that challenge conventional paradigms. Each resolved question invariably reveals a fresh horizon of intriguing questions, reminding scientists of the vast mysteries that remain unsolved. The scientific enterprise is inherently humble, self-correcting, and deeply collaborative, built upon the peer-reviewed contributions of researchers across international borders and disciplinary boundaries. By cultivating sustained curiosity, empirical discipline, and open-minded inquiry, humanity continues its collective voyage into the cosmic unknown, inspired by the conviction that the universe is fundamentally intelligible and endlessly worthy of our most dedicated exploration.`;
  } else if (cat === "Philosophy") {
    p1 = `At the intersection of human consciousness, moral judgment, and existential contemplation lies the enduring inquiry into ${title.toLowerCase()}. As classical and modern thinkers have observed, ${sub.toLowerCase()} Since the inception of philosophical dialogue in ancient agoras and contemplative academies, thinkers have wrestled with the fundamental questions of what it means to lead a good life, how we can attain reliable knowledge, and how human communities ought to be organized. Rather than offering simplistic dogmatic assertions, authentic philosophical inquiry invites us to critically interrogate our unexamined presuppositions, expose internal contradictions in our reasoning, and cultivate a deeper capacity for moral clarity. In a world frequently characterized by superficial distractions, algorithmic noise, and polarized rhetoric, the disciplined pursuit of philosophical wisdom remains an indispensable refuge for the reflective mind.`;
    p2 = `When examining the foundational arguments surrounding ${title.toLowerCase()}, one encounters a rich tapestry of dialectical perspectives developed by thinkers across diverse eras. Some philosophers emphasize the primacy of empirical observation and rational deduction, arguing that objective truths can be uncovered through rigorous analytical reasoning and logical consistency. Others foreground the subjective dimensions of human experience, highlighting the existential freedom, ethical responsibility, and emotional vulnerability that accompany every authentic human choice. Through rigorous dialogue and deliberate thought experiments, philosophers dissect concepts such as justice, virtue, agency, and truth, demonstrating that philosophical ideas are never merely abstract intellectual exercises; they directly shape legal frameworks, institutional policies, and individual conduct.`;
    p3 = `Furthermore, this philosophical tradition underscores the vital relationship between personal character and civic responsibility. A just society cannot flourish in the absence of citizens who possess ethical discernment, empathy, and intellectual humility. When individuals cultivate the habit of examining their motives and acknowledging the limits of their own perspective, they become far better equipped to engage in constructive democratic discourse and resolve complex collective conflicts without resorting to coercion. The enduring value of these philosophical insights lies in their ability to transcend temporal and cultural boundaries, providing timeless frameworks for evaluating both everyday ethical dilemmas and the monumental dilemmas presented by emerging scientific and social paradigms.`;
    p4 = `In concluding our reflection on ${title.toLowerCase()}, we are reminded that philosophy is not a destination or a closed body of doctrine, but an ongoing way of living with conscious intentionality. It calls upon each individual to pause amid the relentless velocity of daily life, to question automatic habits of thought, and to align personal actions with deeply held core principles. By embracing the rigor, wonder, and compassionate humility of philosophical exploration, we honor the ancient invitation to know ourselves, deepening our empathy for fellow human beings and developing the resilience required to navigate the complexities and uncertainties of the modern human condition.`;
  } else if (cat === "Literature") {
    p1 = `In the vast panorama of world literature and storytelling traditions, few works or themes resonate with as much enduring emotional power as ${title.toLowerCase()}. As literary critics and devoted readers have recognized, ${sub.toLowerCase()} Great stories serve as timeless vessels through which humanity explores its deepest fears, grandest aspirations, and most perplexing moral ambiguities. Through the art of narrative prose, dramatic dialogue, and evocative verse, authors craft immersive imaginative realms that mirror the complexities of the human condition with profound nuance. When we open these literary masterpieces, we are invited to transcend the narrow boundaries of our immediate time and space, inhabiting the minds and circumstances of characters whose struggles illuminate our own unspoken vulnerabilities and desires.`;
    p2 = `The brilliance of ${title.toLowerCase()} lies not only in its thematic depth, but also in its consummate structural and stylistic craftsmanship. Master storytellers deploy pacing, rhythm, symbolism, and psychological insight to construct narratives that resonate across multiple interpretive layers. Through carefully chosen metaphors and vivid descriptions, the author transforms ordinary language into an instrument of exceptional precision, beauty, and emotional resonance. The architecture of the plot, whether following a linear trajectory of tragic descent or weaving a complex polyphonic tapestry of multiple intersecting voices, builds dramatic tension that keeps readers spellbound while gently guiding them toward profound moral, emotional, and psychological epiphanies.`;
    p3 = `Moreover, the historical and cultural context in which these narratives were composed provides essential illumination into the societal anxieties and intellectual currents of their respective eras. Authors frequently operated as insightful cultural critics, using satire, allegory, and poetic drama to expose institutional hypocrisies, critique social inequalities, and challenge prevailing orthodoxies. Yet despite being grounded in specific historical moments, truly great literature possesses an astonishing universality. The core conflicts—loyalty versus ambition, personal desire versus societal duty, the search for identity amid alienation—speak directly to human beings across continents and centuries, proving that the human heart remains remarkably consistent across the ages.`;
    p4 = `To immerse oneself in ${title.toLowerCase()} is ultimately an act of creative empathy and intellectual renewal. In an era dominated by rapid snippets of information and fleeting digital distractions, the sustained engagement required by literary narrative cultivates patience, deepens emotional intelligence, and sharpens our capacity for critical reflection. By accompanying these literary figures on their trials, triumphs, and inward transformations, we discover fresh vocabulary for our own experiences and a renewed appreciation for the extraordinary expressive capacity of human language. Literature reminds us that we are never entirely alone in our struggles, connecting us to a timeless symphony of voices that have sought to make sense of the beauty and tragedy of existence.`;
  } else if (cat === "Technology") {
    p1 = `The rapid trajectory of modern technological innovation is brilliantly epitomized by the development of ${title.toLowerCase()}. As engineers and historians of science have documented, ${sub.toLowerCase()} Throughout the past century, human ingenuity has transformed abstract scientific discoveries into tangible mechanical and digital instruments that reshape our civilization. What began as speculative theoretical models or humble laboratory prototypes has evolved into essential technological infrastructure upon which contemporary commerce, healthcare, communication, and governance depend. By bridging the gap between theoretical physics, materials science, and computational logic, engineers have unlocked unprecedented levels of speed, efficiency, and interconnectedness, ushering human society into an era of unprecedented capability and interdependence.`;
    p2 = `Underpinning the successful execution of ${title.toLowerCase()} is an intricate synthesis of specialized hardware engineering, algorithmic optimization, and rigorous systems design. Engineers must solve complex technical challenges involving signal propagation, thermal dissipation, fault tolerance, energetic efficiency, and cryptographic security. Every component within these sophisticated architectures must operate in synchronized harmony, adhering to rigorous manufacturing tolerances and international interoperability standards. As operational scales expand to accommodate millions of concurrent users or billions of discrete computational operations per second, developers deploy sophisticated abstraction layers and automated feedback mechanisms to ensure reliability and security against unpredictable real-world stresses.`;
    p3 = `However, the immense societal influence wielded by modern technological systems necessitates careful ethical scrutiny and prudent governance. The proliferation of powerful technologies inevitably brings complex challenges regarding data privacy, economic equity, resource consumption, and the preservation of human agency. Technological artifacts are not morally neutral; the architectural choices made by designers directly influence how information is distributed, how power is exercised, and how communities interact. Consequently, forward-looking technologists and civic leaders must collaborate to ensure that emerging innovations are developed transparently, equitably, and with robust safeguards designed to protect vulnerable populations from unintended systemic harms.`;
    p4 = `Looking toward the future, the ongoing evolution of ${title.toLowerCase()} promises to unlock revolutionary possibilities across fields as diverse as healthcare, ecological restoration, education, and planetary exploration. As processing power increases and cross-disciplinary collaborations deepen, we stand on the threshold of breakthroughs that were once confined to the realm of speculative fiction. Realizing this potential while mitigating accompanying risks will require a harmonious integration of technical brilliance, ethical vigilance, and inclusive societal dialogue. By placing human well-being and ecological health at the center of our technological aspirations, we can ensure that these remarkable tools serve to elevate human dignity and expand the boundaries of collective human achievement.`;
  } else if (cat === "Arts & Architecture") {
    p1 = `The aesthetic achievements of human culture find magnificent expression in ${title.toLowerCase()}. As art historians and cultural critics have observed, ${sub.toLowerCase()} Across diverse geographic regions and historic epochs, artists and architects have sought to transcend purely utilitarian demands, elevating spatial design and creative craftsmanship into profound expressions of cultural identity, spiritual reverence, and emotional beauty. When we encounter these sublime creations, whether gazing up at soaring stone vaults or contemplating the subtle chromatic gradations of a master canvas, we experience a heightened awareness of human creative potential. Art and architecture serve as tangible manifestations of a society's deepest values, preserving its worldviews and aspirations in enduring physical forms that continue to inspire awe centuries later.`;
    p2 = `The physical realization of these artistic masterworks required a sophisticated union of aesthetic sensitivity, structural engineering, and deep mastery of materials. Architects and builders had to calculate the distribution of gravitational loads, the acoustic properties of enclosed volumes, and the optical effects of natural illumination filtering through clerestories and porticos. Painters, sculptors, and musicians similarly developed specialized techniques—such as perspective projection, harmonic modulation, and pigment chemistry—that enabled them to translate subtle inner visions into palpable sensory experiences. The resulting harmony between structural form and decorative ornamentation reflects a deliberate pursuit of proportion and equilibrium, often drawing inspiration from mathematical symmetries and organic patterns observed in nature.`;
    p3 = `Furthermore, these artistic monuments functioned as vibrant community centers and civic focal points, shaping the daily rhythms and collective consciousness of the societies that inhabited them. They were sites of sacred rituals, civic celebrations, artistic competitions, and civic governance, where citizens gathered to reaffirm their shared traditions and cultural solidarity. The iconography and decorative motifs embedded within their walls communicated rich allegorical narratives, educating and inspiring literate and illiterate observers alike. By embedding profound philosophical and spiritual narratives into spatial environments, architects and artists created immersive atmospheres that elevated human experience above the mundane demands of daily survival.`;
    p4 = `In our contemporary era of rapid urbanization and standardized construction, the enduring lessons of ${title.toLowerCase()} remain extraordinarily timely and vital. They remind us that the built environment exerts a profound psychological and emotional influence on human well-being, and that beauty is not an unnecessary luxury, but an essential component of a flourishing community. By studying the craftsmanship, ecological sensitivity, and visionary daring of historic creators, contemporary designers can draw inspiration for creating spaces and artworks that nurture the human soul. Art and architecture challenge us to build not merely for expediency or short-term profit, but with reverence for longevity, community, and the timeless human hunger for transcendent beauty.`;
  } else {
    // Earth & Oceans
    p1 = `The planetary systems of our living world exhibit breathtaking scale and intricate thermodynamic complexity, illustrated with unforgettable majesty by ${title.toLowerCase()}. As geologists and marine scientists have documented, ${sub.toLowerCase()} Far from being a passive geological backdrop, our planet is an active, evolving organism where lithosphere, hydrosphere, atmosphere, and biosphere interact in perpetual dynamic equilibrium. When we study these vast geographic features, we are immediately humbled by the colossal natural forces—tectonic uplift, oceanic circulation, glacial sculpting, and climatic cycles—that have operated over millions of years to fashion the diverse landscapes and ecosystems that support the global tapestry of living organisms.`;
    p2 = `The biological and physical dynamics that characterize ${title.toLowerCase()} depend upon delicate ecological balances that have evolved across geological epochs. Within these diverse habitats, millions of species have developed specialized morphological and behavioral adaptations that enable them to thrive in extreme climatic conditions. Microscopic plankton and fungal mycelial networks perform foundational nutrient recycling, anchoring intricate food webs that sustain majestic apex predators and vast migratory populations. Nutrient transport mechanisms, such as upwelling ocean currents and atmospheric dust plumes, demonstrate how localized geological processes deliver life-giving minerals to ecosystems thousands of miles away, underscoring the profound ecological unity of our biosphere.`;
    p3 = `However, these ancient ecological sanctuaries are increasingly experiencing unprecedented stresses resulting from accelerating global anthropogenic changes. Habitat fragmentation, temperature anomalies, shifts in precipitation patterns, and environmental pollution threaten to disrupt delicate equilibrium cycles that have stabilized regional biomes for millennia. When keystone species or fundamental biological pathways are compromised, the cascading consequences reverberate throughout the entire trophic cascade, jeopardizing biodiversity and diminishing the ecological resilience upon which human communities directly depend for clean water, fertile soil, and climate regulation.`;
    p4 = `Protecting and conserving ${title.toLowerCase()} represents one of the most urgent moral and practical imperatives confronting modern civilization. Effective ecological stewardship requires an enlightened synthesis of rigorous scientific research, indigenous ecological wisdom, international diplomatic cooperation, and determined grassroots conservation initiatives. By recognizing that human well-being is indivisibly linked to the vitality of the natural world, we can transition toward sustainable modes of living that respect planetary boundaries and honor the intrinsic value of diverse living systems. When we protect these magnificent landscapes and oceanic realms, we preserve not only indispensable ecological life-support systems, but also boundless reservoirs of wonder, inspiration, and renewal for all future generations.`;
  }

  let p5 = `In scrutinizing the broader systemic implications of ${title.toLowerCase()}, one recognizes how subtle interdependencies often drive monumental historical, scientific, and cultural trajectories. Neither isolated breakthroughs nor solitary failures emerge in a vacuum; they reflect the fertile convergence of societal readiness, empirical persistence, and imaginative daring. As scholars, students, and practitioners continue to re-evaluate this enduring domain, they draw continuous inspiration for addressing contemporary frontiers with wisdom, precision, and renewed ambition.`;

  const rawText = [p1, p2, p3, p4, p5].join(' ');
  const words = rawText.trim().split(/\s+/);
  
  // Calibrate each passage to be precisely 490-500 words (~500 words)
  let calibratedWords = words;
  if (words.length > 500) {
    calibratedWords = words.slice(0, 500);
    // Ensure the last word ends gracefully with a period
    let lastWord = calibratedWords[calibratedWords.length - 1];
    if (!lastWord.endsWith('.') && !lastWord.endsWith('!') && !lastWord.endsWith('?')) {
      lastWord = lastWord.replace(/[,;:]$/, '') + '.';
      calibratedWords[calibratedWords.length - 1] = lastWord;
    }
  }

  const finalText = calibratedWords.join(' ');
  return {
    text: finalText,
    wordCount: calibratedWords.length
  };
}

const targetDir = path.resolve(process.cwd(), 'src/data');
if (!fs.existsSync(targetDir)) {
  fs.mkdirSync(targetDir, { recursive: true });
}

const passages = TOPICS.map(topic => {
  const { text, wordCount } = generatePassage(topic);
  return {
    id: topic.id,
    title: topic.title,
    category: topic.cat,
    difficulty: topic.diff,
    summary: topic.sub,
    text: text,
    wordCount: wordCount,
  };
});

console.log(`Generated ${passages.length} passages!`);
const counts = passages.map(p => p.wordCount);
console.log(`Word Count Range: ${Math.min(...counts)} to ${Math.max(...counts)} words.`);

const outputPath = path.resolve(targetDir, 'passages.json');
fs.writeFileSync(outputPath, JSON.stringify(passages, null, 2), 'utf-8');
console.log(`Saved passages data to ${outputPath}`);
